/**
 * Offscreen document entry. Listens on STREAM_RUN (NOT STREAM_START — that's
 * sidepanel→SW only). Broadcasts STREAM_CHUNK back to all surfaces.
 *
 * The SW pre-resolves URL + headers before sending us the run, so we never
 * touch chrome.storage or the auth flow here.
 */

import { streamErrorMessage, streamFetch } from '@/lib/api/stream';
import { handleMicRun, registerMicKeepalive } from '@/lib/audio/mic-recorder-offscreen';
import type { MicRunPayload } from '@/lib/audio/mic-types';
import { log, startDebugRelay } from '@/lib/debug/log';
import { startWsOffscreenRuntime } from '@/lib/desktop/ws-offscreen';
import { broadcast, on } from '@/lib/messaging/native';
import { CHANNELS } from '@/lib/messaging/schemas';
import {
  type FetchAndParseRequest,
  type FetchAndParseResult,
  fetchUrlAndParse,
} from '@/lib/scrape/fetch-and-parse';
import { handleVideoRun } from '@/lib/video/video-recorder-offscreen';
import type { VideoRunPayload } from '@/lib/video/video-types';

startDebugRelay();
log.info('sys', 'offscreen ready');

// Phase 2 C2.a — co-locate the persistent WS reverse channel runtime in the
// same offscreen document. MV3 permits only one offscreen document per
// extension; the streaming reasons (BLOBS) keep this doc alive, and the WS
// runtime piggybacks on that same lifetime.
startWsOffscreenRuntime();

const inflight = new Map<string, AbortController>();

interface RunArgs {
  runId: string;
  url: string;
  body?: unknown;
  parser?: 'rich-events';
  headers: Record<string, string>;
  /** Optional agent name passed through from the SW for tool log attribution. */
  agentName?: string | null;
  /** Latched permission mode for client tools run during this stream. */
  permissionMode?: 'ask' | 'act';
}

// Mic keepalive: auto-stop capture when no recording surface remains.
registerMicKeepalive();

on<RunArgs, { ok: true }>(CHANNELS.STREAM_RUN, async (args) => {
  log.info('stream', `offscreen run ${args.runId} → ${args.url}`);
  const ctrl = new AbortController();
  inflight.set(args.runId, ctrl);
  let chunkCount = 0;
  try {
    await streamFetch({
      url: args.url,
      headers: args.headers,
      body: args.body,
      ...(args.parser !== undefined && { parser: args.parser }),
      signal: ctrl.signal,
      onOpened: (info) => {
        log.info('stream', `opened ${args.runId}`, info);
        broadcast(CHANNELS.STREAM_OPENED, {
          runId: args.runId,
          conversationId: info.conversationId,
          requestId: info.requestId,
          agentName: args.agentName ?? null,
          permissionMode: args.permissionMode ?? 'ask',
        });
      },
      onEvent: (e) => {
        chunkCount++;
        let payload: Record<string, unknown>;
        if (e.type === 'text') payload = { content: e.content };
        else if (e.type === 'reasoning') payload = { content: e.content };
        else if (e.type === 'event') payload = { eventName: e.eventName, data: e.data };
        else if (e.type === 'error')
          payload =
            e.status !== undefined
              ? {
                  message: e.message,
                  status: e.status,
                  ...(e.code !== undefined && { code: e.code }),
                  ...(e.rejoin !== undefined && { rejoin: e.rejoin }),
                  ...(e.unavailableRunId !== undefined && { unavailableRunId: e.unavailableRunId }),
                }
              : { message: e.message, ...(e.code !== undefined && { code: e.code }) };
        else payload = {};
        if (e.type === 'error') {
          // streamFetch already recorded the full upstream diagnostic in Debug.
          // This channel carries only user-safe recovery copy.
          log.warn('stream', `chunk error ${args.runId}: ${e.message ?? '(no message)'}`);
        } else if (e.type === 'done') {
          log.success('stream', `done ${args.runId} (${chunkCount} chunks)`);
        }
        broadcast(CHANNELS.STREAM_CHUNK, { runId: args.runId, type: e.type, payload });
      },
    });
  } catch (err) {
    log.error('stream', `streamFetch threw ${args.runId}`, err);
    broadcast(CHANNELS.STREAM_CHUNK, {
      runId: args.runId,
      type: 'error',
      payload: { message: streamErrorMessage() },
    });
    broadcast(CHANNELS.STREAM_CHUNK, {
      runId: args.runId,
      type: 'done',
      payload: {},
    });
  } finally {
    inflight.delete(args.runId);
  }
  return { ok: true };
});

// SW asks us to fetch + parse a URL into the standard SoupResult-style
// envelope. Runs in offscreen because it needs DOMParser + the existing
// scrape pipeline.
on<FetchAndParseRequest & { include_extras?: boolean }, FetchAndParseResult>(
  CHANNELS.OFFSCREEN_FETCH_PAGE,
  async (payload) => {
    log.info('stream', `offscreen fetch-page ${payload.url}`);
    const { include_extras, ...req } = payload;
    return fetchUrlAndParse(req, include_extras !== undefined ? { include_extras } : {});
  },
);

on<{ runId: string }, { cancelled: boolean }>(CHANNELS.STREAM_KILL, (payload) => {
  const ctrl = inflight.get(payload.runId);
  if (ctrl) {
    log.info('stream', `kill ${payload.runId}`);
    ctrl.abort();
    inflight.delete(payload.runId);
  }
  return { cancelled: !!ctrl };
});

// Microphone capture runs here (reasons include USER_MEDIA in the offscreen
// document) because side-panel getUserMedia is unreliable. SW forwards
// MIC_REQUEST → MIC_RUN; we do the actual MediaRecorder lifecycle and
// broadcast MIC_EVENT messages back to all surfaces.
on<MicRunPayload, { ok: boolean }>(CHANNELS.MIC_RUN, async (payload) => {
  log.info('audio', 'offscreen: MIC_RUN handler entered', { action: payload.action });
  return handleMicRun(payload);
});

// Tab/display video capture (TASK-003). Offscreen holds the MediaStream +
// MediaRecorder for the active session and broadcasts the encoded blob via
// VIDEO_EVENT.complete on stop. The SW pre-resolves the chrome.tabCapture
// streamId before forwarding so this side never touches chrome.tabCapture.
on<VideoRunPayload, { ok: boolean; reason?: string }>(CHANNELS.VIDEO_RUN, async (payload) => {
  log.info('sys', `video run: ${payload.action} (${payload.sessionId})`);
  return handleVideoRun(payload);
});
